INSERT INTO changelog (title, body, created_at) VALUES ('Поломки з програм — у Telegram з назвою клієнта', 'Коли наша програма (напр. Oselya CRM) повідомляє про помилку або відгук менеджера — тобі в Telegram приходить «⚠️ Поломка · Аква Віта · Oselya CRM» + що сталось + посилання на «Що виправити». Однакова помилка — не частіше разу на годину (решта видно в продукті з лічильником ×N). Знахідки нічного самоаудиту — одним повідомленням «🔎 Самоаудит»: скільки знайшов, скільки важливих, топ-3.
Щоб у повідомленні була назва клієнта — у продукті на «Паспорті» додай клієнта в «Клієнти, які користуються». Вимкнути — Можливості → «Помилки й відгуки з наших програм → мені в Telegram».', datetime('now'));
